import express from 'express';
import authentication from '../middleware/authentication.js';
import gangController from '../controllers/gangController.js';
import campaignAuthentication from '../middleware/campaignAuthentication.js';
const router = express.Router();
router.get('/gangs/batch', authentication.authenticate, gangController.getBatchGangs);
router.get('/gangs/:gangId', authentication.authenticate, gangController.getGangById);
router.post('/gangs', authentication.authenticate, campaignAuthentication.validateGameMaster, gangController.createGang);
router.patch('/gangs/:gangId/characters', authentication.authenticate, campaignAuthentication.validateGameMaster, gangController.updateGangCharacters);
router.patch('/gangs/:gangId/characters/:characterId/profits', authentication.authenticate, campaignAuthentication.validateGameMaster, gangController.distributeProfits);
router.patch('/gangs/:gangId/profits', authentication.authenticate, campaignAuthentication.validateGameMaster, gangController.editGangProfits);
router.post('/gangs/:gangId/reputation', authentication.authenticate, campaignAuthentication.validateGameMaster, gangController.allocateReputation);
router.post('/gangs/:gangId/levelNodes', authentication.authenticate, campaignAuthentication.validateGameMaster, gangController.allocateLevelNodes);
router.delete('/gangs/:gangId', authentication.authenticate, campaignAuthentication.validateGameMaster, gangController.deleteGang);
export default router;
